$_MODULE['<{lggooglereviews}prestashop>help_a481969fefacd2cac4651bc0cad8ace8'] = 'Indicate if you want to show a link to the profile of users who have left their reviews';
$_MODULE['<{lggooglereviews}prestashop>help_4e7c6bc487018fc97dc555c507a10cc0'] = 'Review your business data';
$_MODULE['<{lggooglereviews}prestashop>help_367c548945a796b5e52169e33b27202b'] = 'In the tab \"Statistics\" you can see a statistical summary of your business data in Google My Business';
$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'To use Google Maps and Places APIs, you need to register the application and get an API key. Probably, you already know, but we explain how to obtain this key if you do not know.';
$_MODULE['<{lggooglereviews}prestashop>help_929457b0d047a741db5a051fb3409dab'] = 'How create your Google Maps API KEY';
$_MODULE['<{lggooglereviews}prestashop>help_9620b9481e88199f573c9800e8f2a621'] = 'Follow the instructions below to create an API KEY.';
$_MODULE['<{lggooglereviews}prestashop>help_45887556e1cc6a572c574708e1676ea6'] = 'You must log in with your gmail account or create a new gmail account that you want to associate with your project.';
$_MODULE['<{lggooglereviews}prestashop>help_b4c1815fa181e8d36cba075fb5ea51b8'] = 'Once logged in, you should go to the Google Cloud Platform console:';
$_MODULE['<{lggooglereviews}prestashop>help_6b05e59b1c6f2513ea4ec8811602146c'] = 'In the left side menu, you will go to the APIS and Services section.';
$_MODULE['<{lggooglereviews}prestashop>help_7622adcc5af6e55d3a7667c19c13a6fb'] = 'Write the name of the project and click on the \"CREATE\" button.';
$_MODULE['<{lggooglereviews}prestashop>help_55fd75e5be5f25af27c8e67eb2faa100'] = 'Afterwards, we will click on the button \"ENABLE APIS AND SERVICES\".';
$_MODULE['<{lggooglereviews}prestashop>help_fc45981f4bf623a93720e128bc1a1c10'] = 'For this case, select “API PLACES”.';
$_MODULE['<{lggooglereviews}prestashop>help_7684dbca91a174e239e2a8d062df29b1'] = 'Click on the \"ENABLE\" button.';
$_MODULE['<{lggooglereviews}prestashop>help_824a6c6060cae1ce4265e018736337df'] = 'Once the API is created, in the \"Credentials\" tab. There, click on the link \"Credentials in APIs and services\".';
$_MODULE['<{lggooglereviews}prestashop>help_04ee3b1cdc9f4b27e27ec84255924905'] = 'Copy the API Key that is shown on the screen because we will need it later.';
$_MODULE['<{lggooglereviews}prestashop>help_ebc72db384475b19cabb579e57785996'] = 'You will see that in that same pop-up window, it gives you the option to “Restrict password”. Click on that link if you want that key to only be used in a certain domain, for example.';
$_MODULE['<{lggooglereviews}prestashop>help_449abc375ecc691847413fbc9d739a59'] = 'Once you have restricted the password, if you have wanted, we will have to enter the billing information because otherwise, we will only be allowed to call this API once a day and, sincerely, I hope that your website has more than one visit per day. This does not mean that we are going to be charged anything since Google offers you this service for free for a large number of calls to the API, a number for which an SME business will normally not have to pay. If you exceed the number of views that Google gives you for free, it is likely that the business is going very, very well and that you should have no problem investing a little in this. Even if you don\'t get over it, Google asks you for your billing information in case that happens at some point. On the other hand, for your peace of mind, I tell you that Google allows you to put a limit on calls to its API per month. Therefore, you can limit the number of free calls per month and, thus, you will never be charged; simply, opinions will be stopped if you exceed that number.';
$_MODULE['<{lggooglereviews}prestashop>help_fb9ad09694f5986566d455aca68450a9'] = 'How to enter the billing information?';
$_MODULE['<{lggooglereviews}prestashop>help_719545827e174b52f5007290935e39e1'] = 'Follow the instructions below to enter your billing information.';
$_MODULE['<{lggooglereviews}prestashop>help_78a42223fc0bf73ebd95dea4c186874f'] = 'In the Google Cloud Platform console, if we click on the menu icon with 3 horizontal lines, which is on the far left, the navigation menu will appear. There, we must click on the \"Billing\" item.';
$_MODULE['<{lggooglereviews}prestashop>help_17bdf9283a5ae0b5df854db1dd3dd7c9'] = 'We will click on the button \"Manage billing accounts\".';
$_MODULE['<{lggooglereviews}prestashop>help_d854108423e34b73cf5b3537c4e74e69'] = 'We will click on the button \"Add billing account\" and we will follow the steps indicated by Google, entering the requested information.';
$_MODULE['<{lggooglereviews}prestashop>help_b04a7d3f4f74a068e64d49e24b110c76'] = 'Select the Google payments profile that will be associated with this billing account. You can select an existing profile or create a new one.';
$_MODULE['<{lggooglereviews}prestashop>help_a800cf67d7ea062c818c5e9ee0f661a2'] = 'Finally, in the project that you are configuring, we must enable billing for that project. We will do this in \"Billing\", clicking on \"Link billing account\". We will select the account and click on \"Establish account\".';
$_MODULE['<{lggooglereviews}prestashop>help_1671ed90c633e5d528f47c66a166ed88'] = 'How do I know what the Place ID of my business is?';
$_MODULE['<{lggooglereviews}prestashop>help_dc6d24a4104249b69c2e5c9aa5219d6e'] = 'You can go to this page';
$_MODULE['<{lggooglereviews}prestashop>help_cfff697597811556e2781f9146b228d3'] = 'You just have to enter the name of your business as it appears in Google My Business and it will show you your PLACE ID.';
$_MODULE['<{lggooglereviews}prestashop>help_0bd619dcb1b97765da7df00297813025'] = 'Copy your Google Place ID in your module';
$_MODULE['<{lggooglereviews}prestashop>help_41b7f207a5bb87bc9b1c260f1723ff84'] = 'Where to find your url to request Reviews?';
$_MODULE['<{lggooglereviews}prestashop>help_68687ec484228e020f49b0e928ed12a8'] = 'Log in to your Google My Business account.';
$_MODULE['<{lggooglereviews}prestashop>help_ef1ea00aa6058bfdb2d98c7b4e75f98f'] = 'If you have more than one company in your list, select the one you want to show on your website.';
$_MODULE['<{lggooglereviews}prestashop>help_f343afb0d26a2f95f77a42d91c826a74'] = 'Click the button \"Share profile\"	';
$_MODULE['<{lggooglereviews}prestashop>help_9ee9d25e1ced67fbd20cf2044e8279a7'] = 'You can directly copy the short URL so that your customers can write their reviews.';
$_MODULE['<{lggooglereviews}prestashop>help_8d24d9fde106dfde17d8c8ffd71427a0'] = 'In your module, check \"Yes\" in the option \"Show link to add review\"';
$_MODULE['<{lggooglereviews}prestashop>help_45a492bc2c73886bfda54bd3d90013af'] = 'Include the copied url in the field \"Url to add reviews\"	';
$_MODULE['<{lggooglereviews}prestashop>help_24acebeaacbe556b1c6b2455ace449a0'] = 'Click \"Save\"	';
$_MODULE['<{lggooglereviews}prestashop>help_a0c66f7c856f2f3ddba66b75606ccdad'] = 'These are some of the queries we often see:';
$_MODULE['<{lggooglereviews}prestashop>help_a86756485fe7020269c81ba1b69811e5'] = 'If the place you have created comes out as NOT validated, the following checks must be carried out';
$_MODULE['<{lggooglereviews}prestashop>help_6ed1bbbbc54c2b62ade264c019167de6'] = 'Without entering the billing information the module will not work.';
